# GF(8) multiplication using polynomial x^3 + x + 1
def gf_mul(a, b):
    r = 0
    for i in range(3):
        if b & (1<<i):
            r ^= (a << i)
    # reduce
    for i in range(5, 2, -1):
        if r & (1<<i):
            r ^= (0b1011 << (i-3))  # x^3+x+1 shifted
    return r

# verify closure
for a in range(8):
    for b in range(8):
        assert 0 <= gf_mul(a,b) < 8, (a,b,gf_mul(a,b))

# X[i][j] = 1*i XOR j, Y[i][j] = 2*i XOR j (using GF mult)
X = [[gf_mul(1,i) ^ j for j in range(8)] for i in range(8)]
Y = [[gf_mul(2,i) ^ j for j in range(8)] for i in range(8)]

# check Latin
for M in [X,Y]:
    for r in M:
        assert sorted(r) == list(range(8))
    for c in range(8):
        assert sorted(M[i][c] for i in range(8)) == list(range(8))

# check orthogonal
pairs = set()
for i in range(8):
    for j in range(8):
        pairs.add((X[i][j], Y[i][j]))
assert len(pairs) == 64

flat = sum(X, []) + sum(Y, [])
print(flat)
print(len(flat))
